('cursor', 'Cursor', 'كيرسر', 'محرر كود بالذكاء الاصطناعي — البديل الذكي لـ VS Code', 'كيرسر محرر كود مبني على VS Code مع ذكاء اصطناعي متكامل. يفهم قاعدة الكود بالكامل ويكتب الكود ويصحح الأخطاء ويجيب على الأسئلة داخل المحرر مباشرة.', 'code', 'freemium', 20, null, ARRAY['فهم قاعدة الكود', 'Composer لكتابة كود جديد', 'Chat مع الكود', 'Tab للإكمال التلقائي', 'دعم كل اللغات'], ARRAY['الأفضل للمطورين', 'يفهم السياق الكامل', 'مجاني بسخاء'], ARRAY['يعتمد على نماذج مدفوعة', 'أبطأ أحياناً على الملفات الكبيرة'], 'https://cursor.com', 'https://cursor.com/assets/images/logo.svg', 4.7, 8900, ARRAY['code', 'ide', 'vscode', 'developer', 'productivity'], true, '2023-03-14'),

('replit', 'Replit', 'ريبليت', 'كتابة وتشغيل الكود في المتصفح بالذكاء الاصطناعي', 'ريبليت منصة تطوير سحابية تتيح كتابة الكود في المتصفح مع مساعد AI يكتب ويصحح ويشرح الكود. مثالي للتعلم والنماذج الأولية السريعة.', 'code', 'freemium', 20, null, ARRAY['IDE في المتصفح', 'Ghostwriter AI', 'نشر تلقائي', '50+ لغة برمجة', 'قوالب جاهزة'], ARRAY['لا يحتاج تثبيت', 'مثالي للتعلم', 'نشر سريع'], ARRAY['أبطأ من المحررات المحلية', 'محدود في الذاكرة'], 'https://replit.com', 'https://replit.com/public/icons/favicon-196.png', 4.1, 4500, ARRAY['code', 'browser', 'learning', 'deploy', 'beginner'], false, '2016-05-01'),

('tabnine', 'Tabnine', 'تابناين', 'إكمال الكود التلقائي بالذكاء الاصطناعي', 'تابناين إضافة لمحررات الكود تكمل الكود تلقائياً بناءً على سياق مشروعك. يعمل داخلياً (on-device) مما يضمن خصوصية الكود. يدعم كل المحررات الرئيسية.', 'code', 'freemium', 12, null, ARRAY['يعمل داخل VS Code وغيرها', 'خصوصية الكود', 'نموذج مدرّب على كودك', 'دعم 30+ لغة', 'يعمل offline'], ARRAY['خصوصية الكود محفوظة', 'يتعلم من كودك', 'يعمل بدون إنترنت'], ARRAY['أقل ذكاءً من Copilot', 'الإصدار المجاني محدود'], 'https://tabnine.com', 'https://www.tabnine.com/wp-content/uploads/2023/11/tabnine-logo.svg', 3.9, 1200, ARRAY['code', 'autocomplete', 'privacy', 'offline', 'vscode'], false, '2019-06-01'),

('bolt-new', 'Bolt.new', 'بولت', 'بناء تطبيقات ويب كاملة بمحادثة', 'بولت من StackBlitz يبني تطبيقات ويب كاملة في المتصفح بمجرد وصف ما تريد. ينشئ الكود ويثبت المكتبات ويعرض النتيجة فوراً. ثورة في بناء النماذج الأولية.', 'code', 'freemium', 20, null, ARRAY['بناء تطبيقات من النص', 'تشغيل فوري في المتصفح', 'دعم React وNext.js', 'نشر على Netlify', 'تعديل بالمحادثة'], ARRAY['سريع جداً للنماذج الأولية', 'لا يحتاج تثبيت', 'مذهل للمبتدئين'], ARRAY['غير مناسب للمشاريع الكبيرة', 'حدود شهرية'], 'https://bolt.new', 'https://bolt.new/favicon.svg', 4.5, 3200, ARRAY['code', 'web', 'prototype', 'no-code', 'react'], false, '2024-10-01'),

