('otter-ai', 'Otter.ai', 'أوتر AI', 'تفريغ الاجتماعات والمحادثات تلقائياً', 'أوتر AI يسجّل ويفرّغ الاجتماعات تلقائياً ويلخّصها ويستخرج النقاط الرئيسية. يتكامل مع Zoom وGoogle Meet وMicrosoft Teams.', 'productivity', 'freemium', 17, null, ARRAY['تفريغ تلقائي', 'تلخيص الاجتماعات', 'تكامل مع Zoom وMeet', 'بحث في النصوص', 'مشاركة الملاحظات'], ARRAY['دقيق في التفريغ', 'سهل الاستخدام', 'يوفر وقتاً كبيراً'], ARRAY['دقة أقل مع الأصوات غير الإنجليزية', 'محدود في الخطة المجانية'], 'https://otter.ai', 'https://otter.ai/static/images/otter-logo.svg', 4.2, 2300, ARRAY['meeting', 'transcription', 'productivity', 'zoom', 'notes'], false, '2016-02-01'),

('mem-ai', 'Mem.ai', 'ميم AI', 'الذاكرة الثانية الذكية لتنظيم الأفكار', 'ميم AI تطبيق ذاكرة ذكية يحفظ ويرتّب ويسترجع الملاحظات تلقائياً. يجد الروابط بين الأفكار ويجيب على أسئلتك انطلاقاً من ملاحظاتك الشخصية.', 'productivity', 'freemium', 14, null, ARRAY['ذاكرة ذكية', 'ربط الأفكار تلقائياً', 'بحث ذكي', 'تنظيم تلقائي', 'واجهة بسيطة'], ARRAY['لا يحتاج تنظيم يدوي', 'يجد الروابط تلقائياً'], ARRAY['أغلى من المنافسين', 'يفتقر لبعض الميزات المتقدمة'], 'https://mem.ai', 'https://mem.ai/images/mem-logo.svg', 3.9, 430, ARRAY['notes', 'memory', 'knowledge', 'productivity', 'pkm'], false, '2020-01-01'),

('taskade', 'Taskade', 'تاسكيد', 'إدارة المشاريع والمهام بالذكاء الاصطناعي', 'تاسكيد يجمع إدارة المهام والمشاريع والمحادثة الجماعية في أداة واحدة مع مساعد AI. يولّد المهام ويعدّ الخطط ويوزّع العمل تلقائياً.', 'productivity', 'freemium', 19, null, ARRAY['مهام ومشاريع AI', 'محادثة جماعية', 'خرائط ذهنية', 'قوالب AI', 'تعاون الفريق'], ARRAY['شامل في ميزاته', 'مناسب للفرق', 'قوالب AI مفيدة'], ARRAY['كثير من الميزات = تعقيد', 'أداء التطبيق أحياناً بطيء'], 'https://taskade.com', 'https://www.taskade.com/static/images/logos/taskade-logo.svg', 4.0, 670, ARRAY['productivity', 'tasks', 'projects', 'team', 'ai-assistant'], false, '2017-09-01'),

