('semrush-ai', 'Semrush AI', 'سيمراش AI', 'أقوى أداة SEO مع ميزات الذكاء الاصطناعي', 'سيمراش منصة SEO شاملة تضم ميزات AI لتحليل الكلمات المفتاحية والمنافسين وبناء الروابط وتحسين المحتوى. المعيار الذهبي في مجال SEO.', 'seo', 'paid', 139, null, ARRAY['تحليل الكلمات المفتاحية', 'تحليل المنافسين', 'بناء الروابط', 'ContentShake AI', 'تحليل الموقع'], ARRAY['الأشمل في SEO', 'بيانات دقيقة', 'أدوات AI مدمجة'], ARRAY['سعر مرتفع جداً', 'معقد للمبتدئين'], 'https://semrush.com', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Semrush-logo-2022.svg/120px-Semrush-logo-2022.svg.png', 4.5, 6700, ARRAY['seo', 'keywords', 'competitor', 'backlinks', 'professional'], false, '2008-01-01'),

('surfer-seo', 'Surfer SEO', 'سيرفر SEO', 'تحسين محتوى المقالات للتصدر في Google', 'سيرفر SEO يحلّل المقالات المتصدرة ويعطيك توجيهات دقيقة لتحسين محتواك. يقترح الكلمات المفتاحية والعناوين والطول المثالي للمقال.', 'seo', 'paid', 99, null, ARRAY['تحليل SERP', 'Content Editor', 'Audit للموقع', 'Grow Flow', 'Keyword Research'], ARRAY['توجيهات دقيقة للمحتوى', 'سهل الفهم', 'نتائج واضحة'], ARRAY['سعر مرتفع', 'يركز على المحتوى فقط'], 'https://surferseo.com', 'https://surferseo.com/wp-content/themes/surferseo-theme-v2/src/img/surfer-logo.svg', 4.3, 2100, ARRAY['seo', 'content', 'optimization', 'google', 'writing'], false, '2017-01-01'),

('ahrefs', 'Ahrefs', 'أهريفز', 'تحليل الروابط الخلفية والكلمات المفتاحية', 'أهريفز منصة SEO قوية تتميز بأكبر قاعدة بيانات روابط خلفية. تساعد على تحليل المنافسين واكتشاف فرص الكلمات المفتاحية وتتبع الترتيب.', 'seo', 'paid', 129, null, ARRAY['قاعدة بيانات الروابط الأكبر', 'Site Explorer', 'Keywords Explorer', 'Content Explorer', 'AI Content Helper'], ARRAY['بيانات الروابط الأدق', 'واجهة احترافية', 'تحديثات متكررة'], ARRAY['سعر مرتفع', 'معقد للمبتدئين'], 'https://ahrefs.com', 'https://static.ahrefs.com/static/assets/img/ahrefs-logo-print.svg', 4.6, 4300, ARRAY['seo', 'backlinks', 'keywords', 'competitor', 'professional'], false, '2010-07-01'),

