('figma-ai', 'Figma AI', 'فيغما AI', 'تصميم واجهات المستخدم بمساعدة الذكاء الاصطناعي', 'فيغما AI ميزات الذكاء الاصطناعي المدمجة في فيغما تشمل Make Designs لتوليد التصاميم من النص وSearch الذكي واقتراحات التصميم التلقائية.', 'design', 'freemium', 15, null, ARRAY['Make Designs', 'بحث ذكي', 'اقتراحات تلقائية', 'تصدير المكونات', 'تعاون الفريق'], ARRAY['مدمج في Figma', 'معيار الصناعة', 'مجاني للبدء'], ARRAY['AI لا يزال تجريبياً', 'يحتاج تعلم Figma أولاً'], 'https://figma.com', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Figma-logo.svg/100px-Figma-logo.svg.png', 4.4, 7800, ARRAY['design', 'ui', 'ux', 'figma', 'prototype'], true, '2024-06-26'),

('looka', 'Looka', 'لووكا', 'تصميم شعارات احترافية بالذكاء الاصطناعي', 'لووكا يصمم شعارات احترافية بناءً على اسم شركتك ومجالها وتفضيلاتك. يولّد عشرات الخيارات في ثوانٍ ويوفر حزمة هوية بصرية كاملة.', 'design', 'paid', 20, null, ARRAY['شعارات AI', 'هوية بصرية كاملة', 'بطاقات عمل', 'ملفات للطباعة', 'تخصيص كامل'], ARRAY['سهل جداً', 'نتائج احترافية', 'حزمة هوية بصرية'], ARRAY['مدفوع للتحميل', 'لا يناسب العلامات الكبرى'], 'https://looka.com', 'https://looka.com/og/looka-logo.png', 4.1, 3200, ARRAY['logo', 'branding', 'design', 'business', 'identity'], false, '2016-01-01'),

('khroma', 'Khroma', 'خروما', 'توليد لوحات ألوان بالذكاء الاصطناعي', 'خروما يتعلم تفضيلاتك اللونية ثم يولّد لوحات ألوان لا نهاية لها مناسبة لمشاريعك التصميمية. مجاني تماماً ومثالي للمصممين.', 'design', 'free', null, null, ARRAY['لوحات ألوان لا محدودة', 'يتعلم من تفضيلاتك', 'معاينة على نصوص وأزرار', 'حفظ اللوحات المفضلة', 'مجاني'], ARRAY['مجاني تماماً', 'لوحات مخصصة', 'سهل الاستخدام'], ARRAY['لا يصدر ملفات تصميم', 'ميزات محدودة'], 'https://khroma.co', 'https://khroma.co/img/logo.svg', 4.0, 280, ARRAY['design', 'colors', 'palette', 'free', 'ui'], false, '2018-01-01'),

