('julius-ai', 'Julius AI', 'جوليوس AI', 'تحليل البيانات ورسم الرسوم البيانية بالمحادثة', 'جوليوس AI يحلّل ملفات Excel وCSV ويرسم رسوماً بيانية ويجيب على أسئلتك عن البيانات بالمحادثة. لا يحتاج مهارات برمجية.', 'data', 'freemium', 22, null, ARRAY['رفع ملفات Excel وCSV', 'رسوم بيانية تلقائية', 'تحليل إحصائي', 'Python مدمج', 'تقارير PDF'], ARRAY['سهل بدون برمجة', 'رسوم بيانية احترافية', 'يجيب بالعربية'], ARRAY['حدود في الخطة المجانية', 'أحياناً بطيء على الملفات الكبيرة'], 'https://julius.ai', 'https://julius.ai/logo.png', 4.3, 890, ARRAY['data', 'excel', 'charts', 'analysis', 'no-code'], false, '2023-06-01'),

('obviously-ai', 'Obviously AI', 'أوبفيوسلي AI', 'بناء نماذج تنبؤية بدون كود', 'أوبفيوسلي AI يبني نماذج تنبؤية من بياناتك في دقائق بدون كتابة سطر كود واحد. يتنبأ بالمبيعات ومعدلات التوقف وغيرها.', 'data', 'paid', 75, null, ARRAY['نماذج تنبؤية', 'بدون كود', 'تحليل CSV', 'API للنتائج', 'تقارير آلية'], ARRAY['لا يحتاج مهارات AI', 'سريع جداً', 'نتائج قابلة للتفسير'], ARRAY['سعر مرتفع', 'محدود للبيانات الكبيرة جداً'], 'https://obviously.ai', 'https://obviously.ai/logo.png', 3.8, 340, ARRAY['data', 'prediction', 'ml', 'no-code', 'business'], false, '2019-01-01'),

